   249
   250    if (data->d_buf == NULL || data->d_size == 0)
   251      /* No data actually available, ignore it. */
   252      return result;
   253
   254    /* We can now read the section data into results. */
   255    result->sectiondata[cnt] = data;
   256
   257    /* If the section contains string data, we want to know a size of a prefix
   258       where any string will be null-terminated. */
   259    enum string_section_index string_section_idx = scn_to_string_section_idx[cnt];
   260    if (string_section_idx < STR_SCN_IDX_last)
   261      {
   262        size_t size = data->d_size;
   263        /* Reduce the size by the number of non-zero bytes at the end of the
   264           section.  */
   265        while (size > 0 && *((const char *) data->d_buf + size - 1) != '\0')
   266          --size;
   267        result->string_section_size[string_section_idx] = size;
   268      }
